def edge_score_for(arr, r,c, board, occ):
 h,w=arr.shape; sc=0
 # compare each cell to occupied neighbors outside this tile
 for y in range(h):
  rr=r+y
  if c>0 and occ[rr,c-1]:
   a=int(arr[y,0]); b=int(board[rr,c-1]);
   if a==b and a not in (0,1): sc+=1
