   a=int(arr[0,x]); b=int(board[r-1,cc]);
   if a==b and a not in (0,1): sc+=1
  if r+h<N and occ[r+h,cc]:
   a=int(arr[-1,x]); b=int(board[r+h,cc]);
   if a==b and a not in (0,1): sc+=1
 return sc

def search(score, blanks, rem, board, occ, plan, budget):
